{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    node_to_idx = {node: i for i, node in enumerate(nodes)}
    n = len(nodes)
    parent = list(range(n))
    rank = [0] * n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    edges = []
    for a, b, d in distances:
        w = max(core[a], core[b], d)
        if a < b:
            edges.append((w, a, b))
        else:
            edges.append((w, b, a))
    edges.sort()
    mst_edges = []
    total_weight = 0.0
    for w, a, b in edges:
        if union(node_to_idx[a], node_to_idx[b]):
            mst_edges.append([a, b, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError("Graph is disconnected")
    return {"mst_edges": mst_edges, "total_weight": total_weight}"
}
